UPDATE "experiences" SET "name" = 'Music Production Experience', "short_name" = 'Music production', "tagline" = '', "summary" = 'Two hours in a historic East Village recording studio. Build a beat from scratch, record your own vocals and leave with the music you made.', "description" = 'Buzz in, head upstairs and step into the room where Jay Critch, Ron Suno, Ruben Blades and Making Movies have recorded. Alex gives you a tour of the studio, then hands you the controls. You''ll pick sounds, build a beat from nothing, step into the vocal booth and learn the tricks producers use on real records. No experience needed. Most guests have never made music before.', "highlights" = '["Tour a historic East Village studio","Build a beat from scratch","Record your own vocals in the booth","Learn the tricks producers use on real records","Leave with your music"]'::jsonb, "includes" = '["All studio gear and software","A bounced audio file of the music you create","Pictures from your experience"]'::jsonb, "good_to_know" = '["Ages 10 and up","Shared session, up to 15 guests","Extra hours are $150 per hour","Please arrive on time. Sessions are scheduled and reserved in advance, so we can''t guarantee extra time for late arrivals","Sessions in English or Spanish"]'::jsonb, "duration_options" = '[{"minutes":120,"priceCents":15000},{"minutes":180,"priceCents":15000,"flatCents":15000},{"minutes":240,"priceCents":15000,"flatCents":30000}]'::jsonb, "min_guests" = 1, "max_guests" = 15, "location_area" = 'East Village, Manhattan', "address" = '602 East 14th Street, New York, NY 10009', "arrival_instructions" = 'Press the buzzer when you arrive and we''ll bring you upstairs. Please arrive on time.', "is_placeholder" = false, "updated_at" = now() WHERE "slug" = 'music-production';
--> statement-breakpoint
UPDATE "experiences" SET "name" = 'Learn to DJ Experience', "short_name" = 'Learn to DJ', "tagline" = '', "summary" = 'Get behind pro Pioneer decks in a Brooklyn studio. Learn how DJs blend two songs into one, then record a mix of your own to take home.', "description" = 'Club-standard Pioneer CDJs and mixer and a proper sound system. Alex walks you through how DJs line up two songs so they sound like one: beatmatching, EQ, cutting and dropping on cue. Each participant brings 5 songs, and by the end you''ll record a mix of your own.', "highlights" = '["Pro Pioneer CDJs and club mixer","Learn to beatmatch by ear","Blend, cut and drop on cue","Record your own mix with the 5 songs you bring"]'::jsonb, "includes" = '["All DJ gear and headphones","A recording of the mix you create"]'::jsonb, "good_to_know" = '["Each participant prepares 5 songs for their recorded mix","Shared session, up to 5 guests","Extra hours are $150 per hour","Please arrive on time. Sessions are scheduled and reserved in advance, so we can''t guarantee extra time for late arrivals","Sessions in English or Spanish"]'::jsonb, "duration_options" = '[{"minutes":120,"priceCents":13500},{"minutes":180,"priceCents":13500,"flatCents":15000},{"minutes":240,"priceCents":13500,"flatCents":30000}]'::jsonb, "min_guests" = 1, "max_guests" = 5, "location_area" = 'Bushwick, Brooklyn', "address" = '96 Knickerbocker Ave, Brooklyn, NY 11237', "arrival_instructions" = 'Please arrive on time, with your 5 songs ready.', "is_placeholder" = false, "updated_at" = now() WHERE "slug" = 'dj-session';
--> statement-breakpoint
UPDATE "experiences" SET "name" = 'Meditation Experience', "short_name" = 'Meditation', "tagline" = '', "summary" = 'An immersive, guided sound meditation: crystal bowls, live soundscapes and projected visuals while you lie back and let the city fall away.', "description" = 'Settle in, close your eyes and let a live, slowly shifting soundscape do the work. Crystal singing bowls, deep tones and immersive visuals fill the room while you rest. No meditation experience needed and nothing to get right. Bookings start at 6 guests, and a session holds up to 15.', "highlights" = '["Live crystal bowls and soundscapes","Immersive projected visuals","A guided breath to land in the room","Original music composed for the experience"]'::jsonb, "includes" = '["Mats and cushions","Live sound","Access to the full meditation recording","The original musical compositions created for the experience"]'::jsonb, "good_to_know" = '["Minimum booking of 6 guests","Up to 15 guests per session","Wear comfortable clothes","Please arrive on time. Sessions are scheduled and reserved in advance, so we can''t guarantee extra time for late arrivals"]'::jsonb, "duration_options" = '[{"minutes":120,"priceCents":8500}]'::jsonb, "min_guests" = 6, "max_guests" = 15, "location_area" = 'Dumbo, Brooklyn', "address" = '45 Main Street, Brooklyn, NY 11201', "arrival_instructions" = 'Please arrive on time so the session can start together.', "is_placeholder" = false, "updated_at" = now() WHERE "slug" = 'sound-meditation';
--> statement-breakpoint
INSERT INTO "events" ("slug", "title", "summary", "description", "start_at", "end_at", "venue", "address", "meetup_url", "rsvp_enabled", "status") VALUES ('electronic-music-production-idea-to-track-2026-11-25', 'Electronic Music Production: From Idea to Track', 'A free, beginner-friendly evening at Mercy Sound Studios on turning a musical idea into an electronic track.', 'Join us at Mercy Sound Studios for an interactive gathering about electronic music production. We''ll walk through how an idea becomes a track: creative workflows, arrangement, sound selection, synthesizers, drum programming and basic production techniques.

Share your own music for feedback, try the synthesizers and drum machines, and meet other producers in New York. No experience required. Free admission with RSVP.', '2026-11-25T23:30:00.000Z', '2026-11-26T01:30:00.000Z', 'Mercy Sound Studios', '602 East 14th Street, New York, NY 10009', 'https://www.meetup.com/raw-planet-nyc-electronic-music-producers/events/317391139/', true, 'published') ON CONFLICT ("slug") DO NOTHING;

--> statement-breakpoint
